class EligibilityCandidate(BaseModel):
    """
    A model not in the library yet, judged by its facts
    (library-sources-and-engines.md, LS2): a version in a catalogue
    repo, a starter entry, or a search row. The library's catalogue
    answers carry these ready to send back (`CatalogueCandidate.facts`,
    `StarterModel.facts`, `CatalogueSearchResult.facts`), so a caller
    derives nothing itself.

    The same terms as a library model's, with one difference: here an
    absent fact is *not known yet*, where on a library model it means
    *unreadable*. A term that constrains a fact nobody knows cannot be
    checked, so a match resting on it is at best `may_run` (an
    `after_preparation` match stays one), its reason names what was
    assumed, and the answer is `approximate`.

    """

    id: str = Field(
        ...,
        description="The caller's handle for it, echoed as `ModelEligibility.modelId`.\nOpaque; unique within one request.\n",
    )
    format: ModelFormat
    architecture: str | None = Field(
        None,
        description="GGUF's `general.architecture`, as the hub read it from the\nrepo's GGUF, or a safetensors folder's `architectures[0]`, from\nits remote `config.json`.\n",
    )
    quantization: str | None = Field(
        None,
        description="The GGUF quantization, from the file's name (the scan's own fallback).",
    )
    file: str | None = Field(
        None,
        description="The file's name without its folder: a GGUF's first shard\n(`ModelRequirement.files`, LS4). Absent: not known yet, as on a\nsearch row, which names a repo rather than a file.\n",
    )
    sizeBytes: int | None = Field(
        None,
        description="The weights' size: every file the engine loads, shards included,\nwithout a separate vision projector, as the hub lists them (LS6,\nfor an engine's fit). Absent: not known yet, as on a search row,\nand then no engine's fit is estimated for it.\n",
        ge=0,
    )
    mlxQuantized: bool | None = Field(
        None,
        description="Whether the folder's `config.json` carries MLX's quantization\nblock (`MlxQuantizationRule`). Absent: not known.\n",
    )
    approximate: bool | None = Field(
        False,
        description="Guessed from a search row's tags and the hub's repo-level\nmetadata rather than read from one version's files: a repo can\nhold many versions, and only its detail lists them.\n",
    )


class EngineVerdictKind(StrEnum):
    """
    One model against one engine. `runs`: a requirement with authority
    `eugene` matches. `may_run`: only the engine can tell, at load, or
    (for an `EligibilityCandidate`) a term rests on a fact not known
    yet. `after_preparation`: it runs once the engine prepares it.
    `no`: no requirement matches, and `reason` says which term failed.

    """

    runs = 'runs'
    may_run = 'may_run'
    after_preparation = 'after_preparation'
    no = 'no'


class EligibilityLevel(StrEnum):
    """
    The one dot a model carries (Troy's L5, 2026-10-09), in his words:

    * `works_here`: *Will work on this machine now*. An available
      engine `runs` or `may_run` it.
    * `other_engine`: *Will work with a different engine*. An engine
      this node could install would run it, or an available engine
      runs it after preparation.
    * `not_here`: *Can not work on this machine*. No engine this
      hardware can have accepts it, or (when the request asked for fit,
      LS6) every engine that would run it says it does not fit
      (`EngineFit.verdict` `no`).

    An engine whose fit is `no` counts as one that cannot run the
    model, so a model too large for llama.cpp that Strata runs after
    preparing it is `other_engine`. A fit that is *not estimated*, or
    `unknown`, never counts against a model: only a measured `no` does.

    """

    works_here = 'works_here'
    other_engine = 'other_engine'
    not_here = 'not_here'


class FitModelKind(StrEnum):
    """
    How an engine uses memory, so its fit is its own (LS6, Troy's L11;
    library-sources-and-engines.md §6.1). Engines differ in both
    directions, so one engine's arithmetic is never another's answer.

    * `spill` (llama.cpp): weights, the KV cache for the context and an
      overhead allowance against the cards' free memory; what does not
      fit moves to system memory, experts first on a mixture-of-experts
      model (`FitOffload`). The library's arithmetic since M3.
    * `reserved_share` (vLLM): the engine takes a share of each card's
      **total** memory when it starts (`gpuMemoryUtilization`) and
      refuses to start when less than that is free; weights and
      overhead come out of the share and the KV cache must hold the
      whole context in what is left. The model is split evenly across
      the cards it uses (tensor parallel). Nothing spills to system
      memory, so there is no `split`. Read off vLLM's own
      `request_memory` (upstream main, 2026-10-09).
    * `engine_table`: the engine's own table of what each model it runs
      needs, applied to this node by its adapter (`EngineFitModel.table`):
      Strata's setup's RAM figures and its low-RAM and RAM-budget modes.

    """

    spill = 'spill'
    reserved_share = 'reserved_share'
    engine_table = 'engine_table'


class FitQuestion(BaseModel):
    """
    Ask the judge for each engine's fit as well (LS6): the node's
    memory as the caller measured it (the console the picked node's
    devices, as for `GET /v1/models/{id}/fit`), and the context to score
    at. A sum over cards is spread evenly across `gpuCount` of them.

    """

    contextLength: int | None = Field(
        None, description="Absent: the library's `guidanceContextLength`.", ge=1
    )
    vramFreeBytes: int | None = Field(
        None, description="Free memory on the node's cards, summed.", ge=0
    )
    vramTotalBytes: int | None = Field(
        None,
        description="Their total memory, summed. A share-taking engine's share is of\nthis (`reserved_share`). Absent: taken as `vramFreeBytes`.\n",
        ge=0,
    )
    gpuCount: int | None = Field(
        None,
        description='How many cards the sums cover. Absent: one when there is VRAM, none otherwise.',
        ge=0,
    )
    ramAvailableBytes: int | None = Field(None, ge=0)
    ramTotalBytes: int | None = Field(None, ge=0)
    unifiedMemory: bool | None = Field(
        None,
        description='One pool shared with system memory (`MemoryBudget.unifiedMemory`).',
    )


class FitVerdict(StrEnum):
    """
    Lives here since LS6, because an engine's fit (`EngineFit`) uses it
    as well as the library's `Fit`. For a `spill` engine:

    * `fits` — inside **free** VRAM. Fully offloaded, no host memory
      in the generation path.
    * `tight` — inside total VRAM but not free VRAM. It would fit on
      an idle GPU; something is holding memory right now, and
      closing it is the operator's call.
    * `split` — needs host memory as well. Runnable with partial
      offload, and a decision rather than a failure. How much slower
      depends on what moves, which `Fit.offload` says: experts (a
      MoE model, little slower) or whole layers (much slower).
    * `no` — larger than VRAM and RAM together.
    * `unknown` — there is a GPU here and we could not read how much
      memory it has, so no comparison against it can be made. Added
      2026-09-18 (roadmap R2.3, review §6.2 #28) because the
      alternative was worse than silence: `_intel_gpus` reports
      `vramTotalBytes: 0` for a card whose size `xpu-smi` will not
      state, the verdict then took the *no accelerator* branch,
      compared the weights against host memory, and told a 16 GB Arc
      owner that a 30 GB model **fits** — with `gpuCount: 1` printed
      beside it. Wrong in the direction that runs out of memory at
      load.

      It is a property of the machine and not of the model, so every
      candidate on such a host reports it, including small ones: a
      favourable answer computed against a number we do not have is
      right by luck.

    For a `reserved_share` engine: `fits` when the model and the
    context's cache fit its share and the share is free; `tight` when
    they fit the share but less than the share is free now (the engine
    refuses to start until it is); `no` when they do not fit the share.
    Never `split`.

    For an `engine_table` engine, the engine's own words map onto these:
    Strata's *fits* and RAM-budget mode are `fits`; its low-RAM mode
    (part of the experts on the card, the rest from the SSD) is `split`;
    *tight* (a few GB short, so the system pages) is `tight`; *does not
    fit* is `no`; a node with no graphics card it can read is `unknown`.

    Five values rather than a percentage because a percentage of
    *what* — VRAM, or VRAM plus RAM? — is precisely the ambiguity
    the operator is trying to resolve, and because they have
    different advice. `tight` and `split` are the two the field
    usually collapses into "won't fit", and they are the two worth
    naming.

    """

    fits = 'fits'
    tight = 'tight'
    split = 'split'
    no = 'no'
    unknown = 'unknown'


class RetryDisposition(StrEnum):
    """
    Safe means this attempt did not accept application work and may
    be replayed before any output. Terminal means the request must
    be corrected. Indeterminate means work may have occurred; do not
    replay automatically. Missing classification on a server failure
    is indeterminate, never implicit permission to retry.

    """

    safe = 'safe'
    terminal = 'terminal'
    indeterminate = 'indeterminate'


class Problem(BaseModel):
    """
    Error response shape, modeled on RFC 7807 (problem+json). Every
    Eugene Plexus component returns this for 4xx / 5xx responses.

    """

    type: str = Field(
        ...,
        description='A URI reference identifying the problem type, per RFC 7807.\nModeled as a plain string rather than `format: uri` to keep\nsentinel values like `about:blank` and ergonomic at call sites.\n',
    )
    title: str = Field(..., description='Short human-readable summary.')
    status: int = Field(..., description='HTTP status code.')
    detail: str | None = Field(
        None, description='Human-readable explanation specific to this occurrence.'
    )
    instance: str | None = Field(
        None,
        description='A URI reference identifying the specific occurrence. Modeled\nas a plain string for the same reason as `type`.\n',
    )
    component: str | None = Field(
        None,
        description='Eugene Plexus component name that originated the error\n(e.g. `"gateway"`, `"inference-driver:left"`).\n',
    )
    retryDisposition: RetryDisposition | None = Field(
        None,
        description='Safe means this attempt did not accept application work and may\nbe replayed before any output. Terminal means the request must\nbe corrected. Indeterminate means work may have occurred; do not\nreplay automatically. Missing classification on a server failure\nis indeterminate, never implicit permission to retry.\n',
    )
    retryAfterSeconds: float | None = Field(
        None,
        description='Parsed provider Retry-After delay; a scheduling hint, not permission to replay.',
        ge=0.0,
    )


class Status(StrEnum):
    ok = 'ok'
    degraded = 'degraded'
    error = 'error'


class Health(BaseModel):
    """
    Liveness / readiness response shape.
    """

    status: Status
    version: str | None = Field(None, description='Component version (semver).')
    component: str | None = Field(
        None, description='Component identifier (e.g. `"inference-driver"`).'
    )
    safeMode: bool | None = Field(
        False,
        description="True when the component was started with the agent's\nsafe-mode env var set\n(`EUGENE_PLEXUS_<KIND>_SAFE_MODE=1`) and is therefore\nrunning on built-in defaults instead of its persisted\nconfig. Components in safe mode are reachable for config\nediting (`PATCH /v1/config` writes to disk normally) but\nshould be considered non-functional for their primary\npurpose until restarted without the flag. `status` is\nalso reported as `degraded` while safe mode is in effect.\n",
    )
    details: dict[str, Any] | None = Field(
        None, description='Optional component-specific health detail.'
    )


class ConfigValueType(StrEnum):
    """
    The kind of value a config field holds. The UI uses this to pick
    a renderer (text input, dropdown, password field, etc.).

    Three of these hold more than a scalar. `path_list` is an
    ordered JSON array of directory paths on the component host —
    the library's model roots are the first and so far only user —
    and the UI renders it as an add/remove list of directory pickers
    rather than a text field, because asking someone to
    comma-separate Windows paths is asking for a bug report. Order
    is preserved and meaningful: it is the order the operator sees,
    and M3's downloader offers the first entry as the default
    destination.

    `url_list` is the same argument one type over: an ordered JSON
    array of URLs, rendered as an add/remove list of address fields.
    Added at M5 for the control root's standby endpoints, which are
    inherently plural — *"N standbys is a configuration, not a
    mechanism"* — and which have no natural single-value spelling.
    A comma-separated text field would be the same bug report
    `path_list` exists to avoid, and reusing `path_list` for
    addresses would tell every UI to open a directory picker.
    Validation is the field's business rather than the type's; what
    the type promises is a list whose entries are addresses.

    `runtime_name` holds the `name` of a supervised engine runtime,
    and UIs render it as a dropdown sourced from the agent's
    `GET /v1/runtimes`. It exists because `componentKindHint` cannot
    do this job: a runtime is deliberately not a component, so
    `/v1/components` does not list one. What is saved is the
    runtime's *name*, never its URL — the agent assigns the port
    when the operator does not pick one, so a stored URL would
    encode a number the operator never chose and does not own, and
    would be wrong the moment the runtime moved. Its first user is
    the inference-driver's `runtimeName`, which is how a driver
    follows the engine process it fronts.

    `node_name` holds the `name` of an enrolled node, rendered as a
    dropdown sourced from the control root's `GET /v1/nodes`. Same
    reasoning as `runtime_name` one level up: a node is not a
    component either, so `componentKindHint` cannot source it, and
    what is saved is the name rather than a URL because the address
    of a host is topology the control root owns.

    `model_slots` is the gateway's priority-list surface, and the
    one value here that holds objects. An ordered JSON array of
    `{"model": <alias a client asks for>, "targets": [<model id>,
    ...]}`: a request for `model` is served by the drivers serving
    `model` itself, then by the drivers serving each target in
    order, cascading on failure. Targets are **model ids, not driver
    names**, because a model id names a replica set — every driver
    currently serving it, load-balanced — and a driver name would
    name one process. That is why the value reserved since M2 as
    `driver_list` was renamed when M6 defined it: the old name said
    the wrong thing about what goes in the list. A cloud
    subscription is a target like any other, because a
    `claude_code_cli` driver already serves a model id. UIs without
    a structured renderer for it fall back to editing the JSON.

    `path_mappings` (M11) is an ordered JSON array of `PathMapping`
    — `{"from": <a directory as another machine states it>, "to":
    <the same directory on this host>}`. Its one user is the agent's
    `pathMappings`, which is how a node opens model files a library
    on another host described by *its* path: `/models` on the NAS
    is `Z:\\models` here. UIs render it as rows of two directory
    fields, the right-hand one browsable on the component's own
    host, and offer the library's configured roots as suggestions
    for the left. Matching, precedence and translation rules are on
    the agent's field description, not here — the type promises a
    list of pairs and nothing about what they mean.

    `library_folders` (2026-09-14) is an ordered JSON array of
    `LibraryFolder` — `{"path": <a directory on the library's
    host>, "mounts": [<where other machines find the same
    directory>, ...]}`. Its one user is the library's `modelRoots`,
    which was a `path_list` until the reach of a folder moved onto
    the folder: a folder is one exported share, mounted the same
    way on every node of one OS, so the library says where once and
    every node inherits it rather than each node carrying a row per
    folder. A bare string is accepted wherever a `LibraryFolder` is
    expected and means a folder with no mounts — so a config file,
    a PATCH body or a default written for `path_list` still works,
    and `GET /v1/config` always answers in the object form. UIs
    render it as rows of one browsable directory (the library's
    host) plus its mounts; the per-node grid over it is the
    Library's Folders page, not this field.

    `share_credentials` (R2.6, 2026-09-18) is an ordered JSON array
    of `ShareCredential` — `{"host": <a file server>, "username":
    ..., "password": ...}`. Its one user is the agent's
    `shareCredentials`, which is how a host that runs Eugene as a
    Windows **service** reaches an authenticated share at all: a
    service has none of the per-user credentials the person who
    installed it collected by hand. It is the only value here whose
    entries contain a secret, so it carries `secret`'s rule per
    entry rather than per field — the password is redacted in `GET`,
    accepted in `PATCH`, and an entry that omits it keeps the stored
    one. UIs render it as rows of host / user / password, with the
    password a password input, and must not display a redacted
    entry as though its password were empty.

    `string_list` (P1, 2026-09-27) is an ordered JSON array of
    strings with no further meaning to the type: a list of plain
    values the field's own description explains. Its first users are
    the inference-driver's `catalogueInclude` and `catalogueExclude`,
    model-id patterns for a provider account. It exists for the
    reason `url_list` does: a comma-separated text field is a bug
    report, and reusing `path_list` or `url_list` would tell every UI
    to open a directory picker or an address field. UIs render it as
    an add/remove list of text fields.

    `catalogue_sources` (LS4, 2026-10-09) is an ordered JSON array of
    the library's `CatalogueSource` — `{"id", "kind", "label",
    "enabled", "address", "token", "engine"}`: where Discover finds
    models (library-sources-and-engines.md §4.4). Its one user is the
    library's `catalogueSources`, which replaced the single hub
    address and token. Like `share_credentials`, entries hold a
    secret: an `hf_hub` entry's `token` is redacted in `GET` (as
    `null`, with `hasToken` saying whether one is stored), accepted in
    `PATCH`, and an entry that omits it keeps the token stored under
    the same `id`; `""` clears it. UIs render it as rows of a source,
    with the token a password input, and must not display a redacted
    token as though none were stored.

    """

    string = 'string'
    integer = 'integer'
    number = 'number'
    boolean = 'boolean'
    enum = 'enum'
    secret = 'secret'
    file_path = 'file_path'
    path_list = 'path_list'
    url = 'url'
    url_list = 'url_list'
    duration = 'duration'
    runtime_name = 'runtime_name'
    node_name = 'node_name'
    model_slots = 'model_slots'
    path_mappings = 'path_mappings'
    library_folders = 'library_folders'
    share_credentials = 'share_credentials'
    string_list = 'string_list'
    catalogue_sources = 'catalogue_sources'


class ConfigFieldStatusLevel(StrEnum):
    """
    Named rather than inline: an inline enum here generates a class
    called `Level`, and the next inline `level` anywhere in these
    documents would rename it `Level1` under every caller (the S6
    `Source` -> `Source1` trap).

    """

    info = 'info'
    warning = 'warning'


class ConfigFieldShowWhen(BaseModel):
    """
    Predicate over another `ConfigField`'s current value. The UI
    renders the field this is attached to only when the named field
    equals the given value (or matches one entry in the given list).

    """

    key: str = Field(
        ...,
        description='`key` of another field in the same `ConfigSchema` to compare\nagainst.\n',
    )
    equals: Any = Field(
        ...,
        description="Value the named field must equal for this field to render.\nUntyped — when scalar, matches by literal equality against\nthe referenced field's `valueType`. When an array, matches\nif the referenced field's current value equals any entry\n(set-membership). Use the array form for a field that\napplies to multiple entries of an enum (e.g. an `apiKey`\nfield shared across several OpenAI-compatible providers).\n",
    )


class ConfigDocument(BaseModel):
    """
    Current effective config values, keyed by `ConfigField.key`: a
    field with a `default` and no saved value reads as the default.
    A field with `sensitive: true` that holds a value reads as the
    literal string `"<redacted>"`; one that holds none is absent or
    `null`, so a UI never shows a missing key as saved (corrected
    2026-09-30 -- this said `"<redacted>"` "regardless of whether they
    are set", which no component did, and a UI that believed it would
    say a key was saved that never was). Returned by `GET /v1/config`.

    """

    model_config = ConfigDict(
        extra='allow',
    )


class ConfigUpdateRequest(BaseModel):
    """
    Partial update for `PATCH /v1/config`. Every present key is
    set; absent keys are left unchanged. To revert a field to its
    default, send `null` as the value. Sensitive fields are written
    through directly (the redacted form sent back by GET is never
    accepted as a write value).

    """

    model_config = ConfigDict(
        extra='allow',
    )


class ConfigFieldError(BaseModel):
    """
    A per-field validation failure during PATCH.
    """

    key: str
    message: str


class ConfigUpdateResult(BaseModel):
    """
    Outcome of a `PATCH /v1/config` call. Validation failures on
    individual keys do not abort the whole request — valid changes
    are applied, invalid ones are reported in `rejected`.

    """

    applied: list[str] = Field(
        ..., description='Keys that were validated and applied successfully.'
    )
    rejected: list[ConfigFieldError] = Field(
        ...,
        description='Keys whose new values failed validation. The current value\nis preserved.\n',
    )
    requiresRestart: bool = Field(
        ...,
        description='True if any key in `applied` has `requiresRestart: true`,\nmeaning a process restart is needed for the change to take\neffect. The UI should surface this to the user.\n',
    )
    pendingRestart: list[str] | None = Field(
        None,
        description='Keys whose new values are stored but not yet active. Subset\nof `applied`. Empty unless `requiresRestart` is true.\n',
    )


class ConfigTestRequest(BaseModel):
    """
    Optional override for `POST /v1/config/test`. Same shape as
    `ConfigUpdateRequest`: keys override the saved config for the
    duration of the test only. Useful for "Test Connection" UIs where
    the operator wants to verify a new API key, URL, or model
    identifier before committing it. Send an empty body (`{}`) to
    test the saved config as-is.

    """

    overrides: ConfigUpdateRequest | None = None


class ConfigTestResult(BaseModel):
    """
    Result of a `POST /v1/config/test` invocation. Components decide
    what "test" means for their own surface: an inference-driver runs
    a minimal `generate()` round-trip against its backend; the
    gateway probes every driver it can route to; the library checks
    that its configured model directories are readable.

    """

    ok: bool = Field(
        ..., description='True iff the test invocation succeeded end-to-end.'
    )
    component: str = Field(
        ...,
        description='Component identifier (matches `ConfigSchema.component`).\nEchoed for UI clarity when several /v1/config/test responses\nland in the same view.\n',
    )
    latencyMs: int = Field(
        ..., description='Wall-clock time the test took, in milliseconds.'
    )
    summary: str | None = Field(
        None,
        description='One-line human-readable result summary. Always set when\n`ok` is true; may be set on failure to add context beyond\n`error`.\n',
    )
    sampleOutput: str | None = Field(
        None,
        description="Brief sample of the data the test produced — e.g. assistant\ntext from an inference-driver `generate()` round-trip. May be\ntruncated to keep the response small. Omitted when there's\nnothing useful to show.\n",
    )
    error: str | None = Field(
        None,
        description='Human-readable error message. Set when `ok` is false. Should\nbe specific enough that the operator can act on it (e.g.\n`"openaiApiKey rejected: 401 Unauthorized"`).\n',
    )


class SecurityMode(StrEnum):
    """
    How a host retains access to its master encryption key between
    restarts. The component's config schema lists the supported
    subset: the agent offers the first two modes; the control root
    also offers `passphrase_file`.

    * `prompt_on_startup` — passphrase required at every agent
      start. Master key lives only in process memory. Best for
      shared environments, sensitive conversations, security-
      conscious operators. A power outage means Eugene stays
      offline until the operator re-enters the passphrase.
    * `os_keyring` — master key stored in the OS secret store
      (Windows Credential Manager / macOS Keychain / Linux Secret
      Service via the `keyring` Python lib). OS unlocks tied to
      user login; Eugene auto-recovers from restarts. Best for
      home / personal-use installs and anyone who wants minimum
      friction. Anyone with the OS account can also start Eugene.
    * `passphrase_file` — the control root reads a mounted passphrase
      at startup from `EUGENE_PLEXUS_CONTROL_PASSPHRASE_FILE`. For
      containers and other hosts without a keyring. An absent or
      unreadable file leaves the root sealed, with a diagnosis in
      its log. Access to that file permits unlocking the root.

    """

    prompt_on_startup = 'prompt_on_startup'
    os_keyring = 'os_keyring'
    passphrase_file = 'passphrase_file'


class AuthLoginRequest(BaseModel):
    """
    Login request body sent by the UI to `POST /v1/auth/login` on
    the agent. The passphrase is the same one the operator set
    in the wizard. The agent verifies its Argon2id hash; on match,
    issues a session token.

    """

    passphrase: str = Field(..., min_length=1)


class AuthLoginResponse(BaseModel):
    """
    Issued on successful login. The UI stores `sessionToken` as a
    Secure / HttpOnly / SameSite=Strict cookie or in memory; every
    subsequent proxy request includes it as
    `Authorization: Bearer <token>`.

    """

    sessionToken: str = Field(
        ...,
        description='Opaque bearer token; the UI should never inspect its\ncontents. Lifetime is bounded by `expiresAt`.\n\nAn `ep-session+jwt` (see `TrustBundle` for the profile),\nsigned by the control root\'s token key. It is addressed to\nthe machine the operator signed in on and to the control\nroot (`aud: ["node:<name>", "control"]`), or to the root\nalone for a login made there directly. A standalone agent\nthat has not joined an install signs its own. The console\nacts on other machines by exchanging it\n(`control.yaml`, `POST /v1/auth/token`), never by sending\nit on.\n',
    )
    expiresAt: AwareDatetime
    operatorName: str | None = Field(
        None,
        description='The operator\'s display name from the constitution\n(typically "operator" or whatever the operator set).\nEchoed for UI welcome strings.\n',
    )


class TrustGrant(StrEnum):
    """
    What a key in a `TrustBundle` may issue. Checked by every
    verifier against the token's `typ`, `sub` and `aud`:

    * `authority`: the control root's token key, or a standalone
      agent's own. Sessions, exchanged tokens, client keys, and
      service tokens with `sub: control`, to any recipient.
    * `node`: an enrolled agent's token key. Service tokens to **its
      own machine** with any `sub`, and service tokens with
      `sub: agent` to other machines and to `control`.
    * `gateway`: given to a node by the operator's join token, never
      claimed by the node. Service tokens with `sub: gateway` to
      other machines and to `control`.
    * `files`: a Job Site's token key, **instead of** `node`, never
      beside it (`docs/design/remote-nodes.md` §3.2). Service tokens
      with `sub: agent` to `control`, and to **its own machine**.
      Nothing else: a site that joined with a leaked token reaches no
      other machine and no other component, on any network.
    * `standby`: given to **one** node, beside `node`, by an owner's
      `PUT /v1/nodes/{name}/standby` at the control root, never by a
      join token and never claimed by the node
      (`docs/design/warm-standby.md`, SB1). Service tokens with
      `sub: standby` to `control`, and nothing else. The control root
      accepts them on its replication routes alone, and only while
      its applied state still names that node the standby (SB2).

    """

    authority = 'authority'
    node = 'node'
    gateway = 'gateway'
    files = 'files'
    standby = 'standby'


class TrustKey(BaseModel):
    """
    One token-signing key a verifier may accept, and what it may issue.
    """

    kid: str = Field(
        ...,
        description='The RFC 7638 JWK thumbprint of the key: base64url, no\npadding, SHA-256 over\n`{"crv":"Ed25519","kty":"OKP","x":"<base64url public key>"}`.\nA token names its key by this in its `kid` header; a verifier\nrefuses a `kid` its bundle does not list.\n',
    )
    issuer: str = Field(
        ...,
        description='The `iss` a token signed by this key must carry: `control`\nfor the root, `node:<name>` for an enrolled agent, and\n`node:local` for a standalone one.\n',
        pattern='^(control|node:.+)$',
    )
    publicKey: str = Field(
        ..., description='Base64 of the raw 32-byte Ed25519 public key.'
    )
    grants: list[TrustGrant]


class RevokedSession(BaseModel):
    """
    An operator session signed out anywhere in the install. A
    verifier refuses a session whose `jti` is listed, and an
    exchanged token whose `sid` is. Pruned once `exp` has passed.

    """

    jti: str
    exp: int = Field(..., description="The session's own `exp`, unix seconds.")


class TrustBundle(BaseModel):
    """
    The set of keys every verifier in the install trusts, and what
    each may issue. Published by the control root, signed with its
    identity key, carried as the claims of `SignedTrustBundle.jws`.
    Design: `docs/design/per-node-token-keys.md`.

    **The token profile it governs.** Every token is a JWS compact
    JWT with header `{"alg": "EdDSA", "typ": <class>, "kid": <kid>}`
    and claims `iss`, `sub`, `aud` (an array), `iat`, `exp` and
    `jti`. There are three classes:

    * `ep-session+jwt`: an operator session (`sub: operator`), or a
      token obtained from one by exchange, which also carries `act`
      (`{"sub": "node:<asking machine>"}`) and `sid` (the session's
      `jti`).
    * `ep-service+jwt`: a process calling another; `sub` is the
      caller's kind.
    * `ep-client+jwt`: a key an app outside the install holds;
      `jti` is the key's id.

    Recipients are `node:<name>` (every component on that machine),
    `control` (the root), and `gateway` (the install's front door,
    for client keys only).

    **A verifier:**

    1. finds the key by `kid` in the bundle it holds, and refuses an
       unknown one;
    2. takes the algorithm from the key, never from the header;
    3. checks the signature, `exp` and `iat` with a 300 s leeway,
       `typ` against the route's classes, `iss` against the key's
       issuer, `aud` against itself, and the key's `grants` against
       what the token claims;
    4. refuses a token that lives longer than its class allows:
       1 hour for a service token to another machine, 400 days to
       the issuer's own, 14 days for a session, 10 minutes for an
       exchanged token, and 400 days for a client key;
    5. refuses a session that is listed in `revokedSessions`, or
       whose `aud` names a node no longer in the bundle.

    No hard expiry, deliberately. A bundle that stopped verifying
    when the root was dead would end the data path's guarantee to
    outlive it, so a verifier keeps the newest bundle it holds and
    its age is reported instead.

    """

    version: int = Field(
        ...,
        description="The control root's replicated log index when this bundle was\nbuilt, so it only grows, including across a promotion. A\nverifier refuses a lower version than it holds (rollback)\nand replaces its bundle with an equal or higher one.\n",
        ge=0,
    )
    epoch: int = Field(
        ..., description="The control root's epoch; an agent refuses a lower one.", ge=0
    )
    iat: int = Field(
        ...,
        description='When the bundle was signed, unix seconds. Its age is reported, never enforced.',
    )
    authority: str = Field(
        ...,
        description="Base64 of the raw 32-byte Ed25519 public key that signed this\nbundle: the control root's identity key, which every node\npins at enrollment, or a standalone agent's own identity key.\nA verifier refuses a bundle whose `authority` is not the key\nit pinned.\n",
    )
    keys: list[TrustKey]
    revokedSessions: list[RevokedSession]


class SignedTrustBundle(BaseModel):
    jws: str = Field(
        ...,
        description='A JWS compact serialization with header\n`{"alg": "EdDSA", "typ": "ep-trust-bundle+jwt"}`, whose\npayload is a `TrustBundle`, signed with the key its\n`authority` names. The signature covers the payload\'s exact\nbytes, so nothing has to be re-serialized to check it.\n',
    )


class Alg(StrEnum):
    """
    Encryption algorithm identifier.
    """

    secretbox_xsalsa20poly1305 = 'secretbox-xsalsa20poly1305'


class MasterKeyEnvelope(BaseModel):
    """
    Encrypted-at-rest envelope for sensitive config fields. The
    on-disk YAML for fields marked `sensitive: true` is stored as
    this envelope when v0.2 security is enabled; the component
    decrypts using the master key passed in by the agent at
    spawn time (env var `EUGENE_PLEXUS_<KIND>_MASTER_KEY`,
    base64-encoded).

    Algorithm: libsodium secretbox (XSalsa20-Poly1305). The nonce
    is generated per-encryption and stored alongside the
    ciphertext. The master key is 32 bytes derived from the
    operator's passphrase via Argon2id with parameters chosen at
    first-run time and persisted in the agent's state.

    Components MAY accept plaintext values in PATCH requests
    (current behavior); on persist, they encrypt to this envelope
    if the master key is available. GET requests continue to
    return `"<redacted>"` for sensitive fields regardless of
    envelope-vs-plaintext on disk.

    """

    alg: Alg = Field(..., description='Encryption algorithm identifier.')
    nonce: str = Field(
        ...,
        description='Base64-encoded 24-byte nonce. Generated per-encryption,\nnever reused with the same key.\n',
    )
    ciphertext: str = Field(..., description='Base64-encoded ciphertext + auth tag.')


class RestartResult(BaseModel):
    """
    Acknowledgement returned by `POST /v1/admin/restart`. The
    component schedules its own process exit shortly after returning
    this response (typically a few hundred ms — long enough for the
    HTTP response to flush). The component does NOT bring itself
    back up; a process supervisor (systemd, docker-compose, the
    deploy launcher, etc.) is expected to relaunch it. In v0.1
    personal-use deploys without a supervisor, the operator
    relaunches manually.

    """

    scheduled: bool = Field(
        ...,
        description='True if the component accepted the restart and an exit is\nqueued. Always true in v0.1 — the endpoint has no reason to\nrefuse — but typed as a boolean so future versions can gate\non (e.g.) an in-flight long-running operation.\n',
    )
    delayMs: int = Field(
        ...,
        description='How long the component intends to wait before calling exit,\nmeasured from the moment the response is sent. Lets clients\ntime their UI ("restarting in 0.5s…") and decide when to\nstart polling `/healthz` for the relaunched process.\n',
        ge=0,
    )
    message: str | None = Field(
        None,
        description='Optional human-readable note (e.g. "logs flushed, exiting\nnow"). UI may display this in the restart-progress dialog.\n',
    )


class ShareCredential(BaseModel):
    """
    A user name and password this host uses to reach one file server.

    **The unit is the server, not the share**, and that is a Windows
    constraint rather than a simplification: Windows refuses a second
    set of credentials to a server it already holds a session with
    (`ERROR_SESSION_CREDENTIAL_CONFLICT`, 1219), so a per-share
    credential would be a field that cannot always be honoured. One
    entry covers every share on that host.

    **Why this exists at all.** An agent that runs as a Windows
    service has no per-user credential store, so the entry a person
    once typed into Explorer is invisible to it — and at Windows 11
    defaults there is no guest fallback either
    (`EnableInsecureGuestLogons` is 0), so a share that asks for
    nobody in particular is still refused with
    *"your organization's security policies block unauthenticated
    guest access"* (measured 2026-09-18 against the live install's
    own NAS). Without this the agent comes back after a reboot
    unable to read a single model, with every health check green.

    **Per node, and that is `library-folders-and-reach`'s shape
    rather than a departure from it.** A folder states its `mounts`
    once because a mount is a property of the share; a credential is
    a property of *this machine's relationship to* the share, which
    is exactly what `pathMappings` already is. Nodes do not inherit
    credentials, and a folder never carries one.

    Nothing here is required to mount anything: the agent asks the
    OS to establish the session, and an operator who has already
    arranged access another way leaves the list empty.

    """

    host: str = Field(
        ...,
        description="The file server, as the paths that need it spell it — a host\nname or an address, with no leading slashes and no share\nname. `192.168.16.252` covers `\\\\192.168.16.252\\downloads`\nand `\\\\192.168.16.252\\appdata` both. Matched\ncase-insensitively, because a server name is.\n\nA name and an address for the same machine are **two\ndifferent servers** to Windows, which keys a session by the\nname it was dialled with. That is a tripwire worth knowing\nrather than a rule to work around: spell it here the way the\nLibrary folder's mounts spell it.\n",
    )
    username: str = Field(
        ...,
        description='The account on the file server, not on this machine.\n`DOMAIN\\user` where the server wants one.\n',
    )
    password: str | None = Field(
        None,
        description='Redacted in `GET /v1/config` exactly as a `secret` scalar is\n— the value comes back as null and the entry keeps its `host`\nand `username`, so a UI can render the row without ever\nholding the secret. A `PATCH` that omits `password` on an\nentry whose `host` already exists **keeps the stored one**,\nso editing a user name does not silently blank the password;\nan explicit empty string clears it.\n',
    )
    hasPassword: bool | None = Field(
        None,
        description="In `GET /v1/config` only: whether a password is stored for this\nserver. The password itself never leaves the machine, so\nwithout this a row with one and a row without one were\nidentical, and a UI told somebody a password was saved that\nnever was (2026-09-30). Ignored in a `PATCH`.\n\n**At rest it is sealed with the install's master key**, the\nsame envelope a driver's `apiKey` gets, so it is not\nreadable from the config file — and so it is readable only\nonce the agent is unlocked. On a host whose `securityMode`\nis `prompt_on_startup` that means shares are not reachable\nuntil somebody signs in, which is the same thing everything\nelse behind the master key already does and is reported the\nsame way rather than failing as a missing file.\n",
    )


class PathMapping(BaseModel):
    """
    One rule for reading a path that another machine wrote.

    The library describes each model by its path **on the library's
    own host**, and a runtime declaration copies that string
    verbatim — so when the engine runs elsewhere, the agent there is
    handed a path from a filesystem it does not have. A mapping says
    where the same directory is on this host: the NAS's `/models`
    is `Z:\\models` on the Windows box that mounts it. Nothing is
    copied or cached; the operator mounts the share, and this tells
    the agent where they mounted it.

    Shared here because it appears in two places on the agent: as
    the entries of the `pathMappings` config field, and as
    `ModelLocation.mapping` on an admission answer, which reports
    the rule that applied. Two definitions of one pair would drift.

    """

    from_: str = Field(
        ...,
        alias='from',
        description="A directory as the other machine states it — in practice a\nlibrary root, spelled exactly as the library's own\n`GET /v1/config` lists it. Its shape decides how it matches:\na drive letter or UNC prefix means Windows rules (case-\ninsensitive, `/` and `\\` interchangeable); a leading `/`\nmeans POSIX rules. The agent cannot know the library's\noperating system, and the string came from it, so the\nstring stands in.\n",
    )
    to: str = Field(
        ...,
        description="The same directory on the host holding this config. Used\nverbatim, `~` expanded; the remainder of a matched path is\nre-joined onto it with this host's own separator.\n",
    )


class LibraryFolder(BaseModel):
    """
    One directory the library catalogues, and where other machines
    find it (2026-09-14).

    `path` is the directory as the library's own host spells it —
    what the scanner walks, what a `ModelSummary.path` starts with,
    the left-hand side of every rule that reaches it. `mounts` is
    the same directory as **other** machines see it: a POSIX-shaped
    entry is for Linux and macOS nodes, a Windows-shaped one (drive
    letter or UNC) for Windows nodes, and a node takes the first
    entry of its own shape. That is the whole of "how does node X
    reach folder Y" for every node that mounts the share where the
    folder says; a node that mounts it elsewhere carries one
    override in its agent's `pathMappings`, and a node with no
    mount of its shape opens `path` as written — the identical-mount
    convention, and every single-host install.

    The rule this replaces was per node per folder, on each node's
    agent, and grew as nodes × folders with every row typed by hand.
    This is per folder, stated once. Nothing is copied or cached:
    the operator mounts the share, this says where.

    """

    path: str = Field(
        ...,
        description="Absolute, as the library's host spells it. Immutable in the\nsense that changing it is a different folder: models are\nidentified by their path under it.\n",
    )
    mounts: list[str] | None = Field(
        [],
        description='Absolute paths, each Windows- or POSIX-shaped; the shape\nsays which nodes it is for. Order matters only among entries\nof one shape, where the first wins. Empty means "reached at\n`path`, or not at all".\n',
    )


